    # Each band has an intentionally shortened top edge.
    for radius in range(2, max(h, w) + 2, 2):
        top, bottom = cr - radius, cr + radius
        left, right = cc - radius, cc + radius
        start = left + radius // 2
        lines = (
            [(top, c) for c in range(start, right + 1)],
            [(r, right) for r in range(top, bottom + 1)],
            [(bottom, c) for c in range(left, right + 1)],
            [(r, left) for r in range(top, bottom + 1)],
        )
        for line in lines:
            for r, c in line:
                if 0 <= r < h and 0 <= c < w and grid[r][c] != 2:
                    out[r][c] = 3

    # Extend the inner left and right rails to the top of the next band,
    # creating the nested spiral connection.
